import{_ as e,c as i,o,a3 as s}from"./chunks/framework.CoV49S2T.js";const m=JSON.parse('{"title":"Permisos de macOS","description":"","frontmatter":{},"headers":[],"relativePath":"es/guide/permissions.md","filePath":"es/guide/permissions.md","lastUpdated":1787284674000}'),r={name:"es/guide/permissions.md"};function n(c,a,t,l,p,d){return o(),i("div",null,[...a[0]||(a[0]=[s(`<h1 id="permisos-de-macos" tabindex="-1">Permisos de macOS <a class="header-anchor" href="#permisos-de-macos" aria-label="Permalink to &quot;Permisos de macOS&quot;">​</a></h1><p>ClipboxAI puede solicitar algunos permisos de macOS para ofrecer la mejor experiencia. Esta página explica para qué sirve cada permiso y cómo gestionarlo.</p><h2 id="portapapeles-automatizacion" tabindex="-1">Portapapeles / Automatización <a class="header-anchor" href="#portapapeles-automatizacion" aria-label="Permalink to &quot;Portapapeles / Automatización&quot;">​</a></h2><p>Para capturar su portapapeles en segundo plano y pegar los resultados de vuelta, ClipboxAI usa el acceso de Automatización de macOS.</p><p><strong>Para qué se usa</strong>: leer el portapapeles actual cuando copia y escribir los resultados de vuelta cuando ejecuta una acción.</p><p><strong>Gestionar</strong>: <strong>Configuración del sistema → Privacidad y seguridad → Automatización</strong> → active <strong>ClipboxAI</strong>.</p><p>Conceda el acceso cuando se le solicite durante el primer inicio. Puede gestionarlo o revocarlo en cualquier momento.</p><h2 id="accesibilidad-opcional" tabindex="-1">Accesibilidad (opcional) <a class="header-anchor" href="#accesibilidad-opcional" aria-label="Permalink to &quot;Accesibilidad (opcional)&quot;">​</a></h2><p>Algunas compilaciones usan Accesibilidad para ofrecer atajos de teclado globales y activar el panel de historial desde cualquier lugar.</p><p><strong>Para qué se usa</strong>: abrir el panel de historial y ejecutar acciones mediante teclas de acceso rápido, incluso cuando la aplicación no tiene el foco.</p><p><strong>Gestionar</strong>: <strong>Configuración del sistema → Privacidad y seguridad → Accesibilidad</strong> → active <strong>ClipboxAI</strong>.</p><h2 id="notificaciones-opcional" tabindex="-1">Notificaciones (opcional) <a class="header-anchor" href="#notificaciones-opcional" aria-label="Permalink to &quot;Notificaciones (opcional)&quot;">​</a></h2><p>ClipboxAI puede mostrar notificaciones cuando una acción de larga duración finaliza o requiere atención.</p><p><strong>Para qué se usa</strong>: avisarle cuando una acción termina o cuando se requiere configuración.</p><p><strong>Gestionar</strong>: <strong>Configuración del sistema → Notificaciones</strong> → <strong>ClipboxAI</strong>.</p><h2 id="acceso-total-al-disco-opcional" tabindex="-1">Acceso total al disco (opcional) <a class="header-anchor" href="#acceso-total-al-disco-opcional" aria-label="Permalink to &quot;Acceso total al disco (opcional)&quot;">​</a></h2><p>No se requiere para un uso normal. Solo es necesario si desea que la aplicación lea fragmentos de ubicaciones protegidas por el sistema.</p><p><strong>Gestionar</strong>: <strong>Configuración del sistema → Privacidad y seguridad → Acceso total al disco</strong>.</p><p>Este permiso es opcional y solo se necesita en escenarios avanzados.</p><h2 id="restablecer-un-permiso-con-terminal" tabindex="-1">Restablecer un permiso con Terminal <a class="header-anchor" href="#restablecer-un-permiso-con-terminal" aria-label="Permalink to &quot;Restablecer un permiso con Terminal&quot;">​</a></h2><p>Si se descartó un cuadro de diálogo de permiso o el estado es inconsistente, puede restablecer los avisos de permiso de macOS usando <code>tccutil</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Restablecer los avisos de automatización/accesibilidad para ClipboxAI</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tccutil</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> reset</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> All</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> com.w3cub.clipboard</span></span></code></pre></div><p>Tras ejecutar <code>tccutil</code>, reinicie la aplicación y vuelva a activar la función para que se le solicite de nuevo.</p><h2 id="solucion-de-problemas" tabindex="-1">Solución de problemas <a class="header-anchor" href="#solucion-de-problemas" aria-label="Permalink to &quot;Solución de problemas&quot;">​</a></h2><ul><li>Si el historial del portapapeles no captura las copias, compruebe que el permiso de <strong>Automatización</strong> esté concedido.</li><li>Si los atajos globales no funcionan, compruebe el permiso de <strong>Accesibilidad</strong>.</li><li>Tras cambiar los permisos, salga y vuelva a abrir ClipboxAI siempre para que los cambios surtan efecto.</li></ul><p>Para obtener más ayuda, visite la <a href="/es/guide/troubleshooting.html">guía de solución de problemas</a>.</p>`,26)])])}const g=e(r,[["render",n]]);export{m as __pageData,g as default};
